import { createAvatar } from '@dicebear/core';
import * as pixelArt from '@dicebear/pixel-art';
import { stableHash } from '@/components/club-emblem';

/*
 * Pixel-art portraits generated by code (ADR 0010 §4: avatars, never photos).
 * DiceBear core and the "Pixel Art" style are MIT (code) and CC0 (design).
 * The same seed always yields the same picture, so an athlete keeps their
 * face across screens and sessions.
 */

/** Background swatches: artwork colors, not UI tokens (hex without '#'). */
const BACKDROPS = ['246630', '7cc4ea', 'a0672f', 'ffd23f', 'c8322b', '2f7d3a'];

export interface PixelAvatarOptions {
  /** Pixel size of the SVG box (the picture scales crisply). */
  readonly size?: number;
  /** Background hex without '#'; derived from the seed when omitted. */
  readonly backdrop?: string;
  /** Hide the backdrop (transparent picture). */
  readonly transparent?: boolean;
}

export function avatarBackdrop(seed: string): string {
  return BACKDROPS[stableHash(seed) % BACKDROPS.length]!;
}

/** SVG markup of the deterministic pixel avatar for `seed`. */
export function pixelAvatarSvg(
  seed: string,
  options: PixelAvatarOptions = {},
): string {
  const backdrop = options.transparent
    ? []
    : [options.backdrop ?? avatarBackdrop(seed)];
  return createAvatar(pixelArt, {
    seed,
    size: options.size ?? 64,
    backgroundColor: backdrop,
    radius: 0,
  }).toString();
}

/** `data:` URI of the pixel avatar, ready for an `<img src>`. */
export function pixelAvatarUri(
  seed: string,
  options: PixelAvatarOptions = {},
): string {
  const svg = pixelAvatarSvg(seed, options);
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}
